def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the three-row palette strip: each column is a repeated color.
    header = None
    for r in range(h - 2):
        cols = [c for c in range(w) if grid[r][c] != 0 and grid[r][c] == grid[r+1][c] == grid[r+2][c]]
        runs=[]
        for c in cols:
            if not runs or c > runs[-1][-1] + 1: runs.append([c])
            else: runs[-1].append(c)
        candidates=[run for run in runs if len(run)>=3]
        if candidates:
            run=max(candidates,key=len)
            header=(r,run[0],run[-1]+1,[grid[r][c] for c in run])
            break
    if header is None:
        raise ValueError('palette strip not found')
    hr,c0,c1,palette=header
    palette_cells={(rr,cc) for rr in range(hr,hr+3) for cc in range(c0,c1)}
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1 and (r,c) not in palette_cells]
    if not pts: raise ValueError('color-1 template missing')
    rmin=min(r for r,c in pts); rmax=max(r for r,c in pts)
    cmin=min(c for r,c in pts); cmax=max(c for r,c in pts)
    sh,sw=rmax-rmin+1,cmax-cmin+1
    mask={(r-rmin,c-cmin) for r,c in pts}
    start=rmin-palette.index(1)*sh
    out=[[0]*w for _ in range(h)]
    for i,color in enumerate(palette):
        top=start+i*sh
        for dr,dc in mask:
            rr,cc=top+dr,cmin+dc
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=color
    return out
